async function editedShows(c: Locator, f: ClaimFields, was: Record<string, string>): Promise<boolean> {
  for (const [k, v] of Object.entries(f)) {
    const cell = await shown(c.getByTestId(`claim-${k}`));
    if (k === 'ref' || k === 'tags') {
